mapper.select:
select count(*) from batch_retry_targets brt join batch_executions be on be.execution_id = brt.original_execution_id where brt.original_execution_id = #{originalExecutionId} and be.execution_status = 'FAILED'
and brt.failed_item_key = #{failedItemKey}
and brt.failed_item_key is null

select batch_id
from batch_executions
where execution_id = #{originalExecutionId}
